int gets(int l,int r){
	if(l>nw)return 0;
	if(l>r)return 0;
	return dp[min(r,nw)]-dp[l-1];
}
void solve(int x,int res){
	if(mk[x])for(auto c:fs[x])res+=gets(c.l,c.r)*c.op,res%=mods;
	if(x!=1)f[x]=res;
	dp[d[x]]=(dp[d[x]-1]+f[x])%mods;
	nw=d[x];
	while(sm[x]--){
		auto c=fs[x].back();
		fs[x].pop_back();
		res-=gets(c.l,c.r)*c.op;
		res%=mods;
	}
    if(p[x].size()){
    	swap(fs[x],fs[p[x][0]]);
    	solve(p[x][0],res);
    	for(int i=1;i<p[x].size();i++){
    		int c=p[x][i];
    		mk[c]=1;
    		nw=d[x];
    		solve(c,0);
    	}
    }
}
